(()=>{const run=()=>{const home=document.getElementById('home');if(home&&!document.getElementById('mindfulness-complete-20260825')){const card=document.createElement('div');card.className='card';card.id='mindfulness-complete-20260825';card.style.marginBottom='16px';card.innerHTML='<span class="pill">25 AUG · DONE</span><h3 style="margin-top:.7rem">Mindfulness homework completed</h3><p>Did meditation tonight and completed the Chocolate Meditation using favourite Hotel Chocolat chocolate.</p><p><strong>Values showing up:</strong> peace, health without obsession, and living again. After a stressful work day, I still made space to slow down and actually experience something I enjoy.</p>';const hero=home.querySelector('.hero');if(hero)hero.insertAdjacentElement('afterend',card);}const library=document.getElementById('library-grid');if(library&&!document.getElementById('library-franticworld-mindfulness')){const card=document.createElement('div');card.className='card';card.id='library-franticworld-mindfulness';card.innerHTML='<span class="pill">MINDFULNESS</span><h3>Free mindfulness meditations</h3><p>Mindfulness: Finding Peace in a Frantic World. Includes the Chocolate Meditation and other guided mindfulness exercises used for Kirsty homework.</p><p><a href="https://franticworld.com/free-meditations-from-mindfulness/" target="_blank" rel="noopener noreferrer">Open meditation exercises</a></p>';library.prepend(card);}};let n=0;const t=setInterval(()=>{run();if(++n>16)clearInterval(t)},250);})();